print("vis_res keys:", list(vis_res.output.keys()))
for k, v in vis_res.output.items():
    if "handle" in k or "evidence" in k or "provenance" in k or isinstance(v, (str, list)):
        print("vis_res", k, ":", v)

print("m_bell keys:", list(m_bell.output.keys()))
for k, v in m_bell.output.items():
    if "handle" in k or "evidence" in k or "provenance" in k or isinstance(v, (str, list, dict)):
        print("m_bell", k, ":", v)

print("m_stand keys:", list(m_stand.output.keys()))
for k, v in m_stand.output.items():
    if "handle" in k or "evidence" in k or "provenance" in k or isinstance(v, (str, list, dict)):
        print("m_stand", k, ":", v)

handles = []
for res in [vis_res, m_bell, m_stand]:
    if res.ok and isinstance(res.output, dict):
        for k, v in res.output.items():
            if "handle" in k:
                if isinstance(v, str):
                    handles.append(v)
                elif isinstance(v, list):
                    handles.extend(v)
        if "visual_evidence" in res.output and isinstance(res.output["visual_evidence"], dict):
            for k, v in res.output["visual_evidence"].items():
                if "handle" in k:
                    if isinstance(v, str):
                        handles.append(v)
                    elif isinstance(v, list):
                        handles.extend(v)
        if "measurement" in res.output and isinstance(res.output["measurement"], dict):
            for k, v in res.output["measurement"].items():
                if "handle" in k:
                    if isinstance(v, str):
                        handles.append(v)
                    elif isinstance(v, list):
                        handles.extend(v)

print("extracted handles:", handles)
if handles:
    pp_res = primitives.call(
        name="execute_robotwin2_pick_place",
        arm_tag="right",
        evidence_handles=handles,
        source_actor_label="050_bell",
        target_actor_label="074_displaystand",
        pre_grasp_distance=0.08,
        lift_distance=0.1,
        pre_place_distance=0.08,
    )
    print("pp_res ok:", pp_res.ok)
    print("pp_res output:", pp_res.output)

# Check current scene and arm poses
scene_res = primitives.call(name="observe_robotwin2_scene")
if scene_res.ok:
    print("actor_evidence:", scene_res.output.get("actor_evidence"))
    print("arm_schema:", scene_res.output.get("arm_schema"))

# Inspect points of bell and displaystand
for actor in ["050_bell", "074_displaystand"]:
    for pt in ["contact", "functional", "target", "orientation"]:
        r = primitives.call(name="inspect_robotwin2_actor_points", actor_name=actor, point_type=pt)
        if r.ok:
            print(actor, pt, ":", r.output)

print("m_bell2 keys:", list(m_bell2.output.keys()))
for k, v in m_bell2.output.items():
    if "handle" in k or isinstance(v, (str, list)):
        print("m_bell2", k, ":", v)

handles2 = []
for res in [m_bell2, m_stand2]:
    if res.ok and isinstance(res.output, dict):
        for k, v in res.output.items():
            if "handle" in k:
                if isinstance(v, str):
                    handles2.append(v)
                elif isinstance(v, list):
                    handles2.extend(v)

print("handles2:", handles2)
cur_quat = arm_r.output["pose_world"][3:]

for name_pt, pos in [
    ("bell_pre", [0.2215, -0.0415, 0.88]),
    ("bell_grasp", [0.2215, -0.0415, 0.78]),
    ("stand_pre", [0.0276, -0.1163, 0.92]),
    ("stand_place", [0.0276, -0.1163, 0.85]),
]:
    pr = primitives.call(
        name="probe_robotwin2_motion_plan",
        arm_tag="right",
        evidence_handles=handles2,
        target_pose=pos + cur_quat,
    )
    print("probe", name_pt, "ok:", pr.ok, "output:", pr.output)

